export default function KoreanHome() {
  return <SignalAtlasDashboard events={marketEvents} initialLive={liveFallback} locale="ko" />;
}

import type { Metadata } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: "Market Signal Atlas — Public signals and real market reactions",
  description: "Explore real asset prices around reviewed public signals without prediction or causality claims.",
};

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

import { marketEvents } from "@/lib/data";
import { orchestrateEvent } from "@/lib/orchestration";

export const runtime = "nodejs";
export const maxDuration = 60;

export async function POST(request: Request) {
  let eventId = "";
  try {
    const body = await request.json() as { eventId?: string };
    eventId = body.eventId ?? "";
  } catch {
    return Response.json({ error: "Invalid JSON body" }, { status: 400 });
  }
  const event = marketEvents.find((item) => item.id === eventId);
  if (!event) return Response.json({ error: "Signal not found" }, { status: 404 });
  return Response.json(await orchestrateEvent(event));
}

import { NextResponse } from "next/server";
import { getLivePayload } from "@/lib/live";

export const dynamic = "force-dynamic";

export async function GET() {
  const payload = await getLivePayload();
  return NextResponse.json(payload, {
    headers: { "Cache-Control": "public, s-maxage=86400, stale-while-revalidate=3600" },
  });
}


import { marketEvents } from "@/lib/data";
import { getNewsEvidence } from "@/lib/gdelt";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  const eventId = new URL(request.url).searchParams.get("eventId") ?? "";
  const event = marketEvents.find((item) => item.id === eventId);
  if (!event)
    return Response.json({ error: "Signal not found" }, { status: 404 });
  return Response.json(await getNewsEvidence(event), {
    headers: {
      "Cache-Control": "public, s-maxage=86400, stale-while-revalidate=3600",
    },
  });
}

